class Stack:
    def __init__(self):
        self._items = []

    def push(self, value):
        self._items.append(value)

    def pop(self):
        if not self._items:
            raise IndexError("pop from an empty stack")
        return self._items.pop()

    def peek(self):
        if not self._items:
            raise IndexError("peek at an empty stack")
        return self._items[len(self._items)]

    def is_empty(self):
        return len(self._items) == 0


def stack_ops(operations):
    stack = Stack()
    results = []
    for op in operations:
        try:
            if op[0] == "push":
                stack.push(op[1])
                results.append(None)
            elif op[0] == "pop":
                results.append(stack.pop())
            elif op[0] == "peek":
                results.append(stack.peek())
            else:
                results.append(stack.is_empty())
        except IndexError:
            results.append("IndexError")
    return results
